const $=s=>document.querySelector(s);const fmt=n=>Number(n).toLocaleString('th-TH',{maximumFractionDigits:2});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menus=[['tasks','▦','งานของฉัน'],['overview','◫','ภาพรวมธุรกิจ'],['tanks','▤','สาขาและถังน้ำมัน'],['daily','▧','บันทึกประจำวัน'],['receive','↓','รับน้ำมันเข้า'],['use','↑','เบิกใช้น้ำมัน'],['finance','฿','รายรับ–รายจ่าย'],['requests','✓','เบิกเงินและอนุมัติ'],['reports','▥','รายงานและ Excel'],['admin','⚙','จัดการระบบ'],['audit','◷','ประวัติการทำรายการ']];
const roles=['เจ้าของ','Admin','ผู้จัดการสาขา','พนักงาน','นักบัญชี'];let role='เจ้าของ',route='tasks',branch='all';
const branches=[{id:'b1',name:'สาขา 01 · TAI SIAM Tachileik',active:true},{id:'b2',name:'สาขา 02 · TAI SIAM 2',active:true},{id:'b3',name:'สาขา 03 · MOK SIO',active:true},{id:'b4',name:'สาขา 04 · TAI SIAM Murng Pan',active:true}];
function allowed(){return role==='Admin'?['tasks','admin','audit']:role==='พนักงาน'?['tasks','tanks','daily','receive','use','requests']:role==='ผู้จัดการสาขา'?['tasks','tanks','daily','receive','use','requests','reports','audit']:role==='นักบัญชี'?['tasks','finance','requests','reports','daily','audit']:menus.map(x=>x[0])}
function bname(id){return branches.find(b=>b.id===id)?.name||'ทุกสาขา'}function badge(s){return `<span class="badge ${/ปิด|อนุมัติแล้ว|จ่ายแล้ว|ตรวจแล้ว/.test(s)?'green':/ส่งกลับ|ปฏิเสธ|ต่ำ/.test(s)?'red':/รอ|ส่งตรวจ/.test(s)?'amber':'blue'}">${s}</span>`}function go(r){route=r;location.hash=r;render()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">TAISIAM / OPERATIONS</div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}
function tasks(){return head('งานของฉัน','วันอาทิตย์ที่ 27 กันยายน 2569 · งานที่ต้องดูแลวันนี้',`<button class="primary" onclick="go('daily')">เปิดบันทึกประจำวัน ↗</button>`)+`<div class="stats"><div class="stat"><small>สาขาที่ปิดวันแล้ว</small><strong>1 <span class="unit">/ 4 สาขา</span></strong><small>ข้อมูลประจำวันที่ 27 ก.ย. 2569</small></div><div class="stat"><small>รอตรวจข้อมูลประจำวัน</small><strong>1 <span class="unit">สาขา</span></strong><small>ส่งต่อให้ผู้จัดการสาขา</small></div><div class="stat"><small>คำขอเบิกเงินรออนุมัติ</small><strong>1 <span class="unit">รายการ</span></strong><small>ค่าซ่อมอุปกรณ์ · 2,000 บาท</small></div><div class="stat"><small>เงินทดรองค้างเคลียร์</small><strong>2,000 <span class="unit">บาท</span></strong><small>รอส่งหลักฐาน 1 รายการ</small></div></div><div class="grid"><section class="panel"><div class="panelhead"><h2>เริ่มจากงานที่รอคุณ</h2>${badge('3 งานวันนี้')}</div><div class="task"><div class="taskicon">✓</div><div class="taskbody"><h3>คำขอเบิกเงินรออนุมัติ</h3><small>สาขาTAI SIAM Tachileik · เปลี่ยนสายหัวจ่าย · 2,000 บาท</small></div><button onclick="go('requests')">ตรวจคำขอ →</button></div><div class="task"><div class="taskicon">▧</div><div class="taskbody"><h3>ข้อมูลประจำวันรอตรวจ</h3><small>สาขาTAI SIAM 2 · ส่งตรวจเมื่อ 17:20 น.</small></div><button onclick="go('daily')">ดูบันทึก →</button></div><div class="task"><div class="taskicon">!</div><div class="taskbody"><h3>สาขาTAI SIAM Murng Panยังไม่ส่งข้อมูล</h3><small>ยังไม่มีข้อมูลประจำวันที่ 27 กันยายน</small></div><button onclick="branch='b4';go('daily')">ดูสถานะ →</button></div></section><section class="panel"><h2>สถานะทั้ง 4 สาขา</h2>${branches.map((b,i)=>`<div class="task"><div class="taskbody"><h3>${b.name}</h3><small>${['แก้ไขยอดเงินโอนตามหมายเหตุ','รอผู้จัดการตรวจสอบ','ยืนยันแล้วเมื่อ 18:10 น.','รอข้อมูล'][i]}</small></div>${badge(['ส่งกลับแก้ไข','ส่งตรวจ','ปิดวันแล้ว','รอข้อมูล'][i])}</div>`).join('')}</section></div><div class="note">ข้อมูลในต้นแบบเป็นข้อมูลสมมติสำหรับทดลองขั้นตอนทำงาน กรุณาไม่กรอกข้อมูลส่วนตัวหรือเอกสารจริง</div>`}
function render(){const current=menus.find(m=>m[0]===route);$('#app').innerHTML=`<div class="shell"><aside><div class="brand"><div class="mark">ต</div><div><strong>ไตยสยาม</strong><small>ระบบงานปั๊มน้ำมันครอบครัว</small></div></div><div><div class="navlabel">พื้นที่ทำงาน</div><nav class="nav">${menus.filter(m=>allowed().includes(m[0])).map(m=>`<button class="${route===m[0]?'active':''}" onclick="go('${m[0]}')"><span class="ico">${m[1]}</span>${m[2]}</button>`).join('')}</nav></div><div class="sidebottom">4 สาขา · ทำงานไปด้วยกัน<br>ต้นแบบฉบับออกแบบ / 01<br><button onclick="go('login')">ออกจากระบบจำลอง</button></div></aside><div class="workspace"><header class="topbar"><div class="actions"><button class="mobilemenu" onclick="document.querySelector('aside').classList.toggle('open')">☰</button><span>${current?.[2]||'คู่มือระบบ'}</span></div><div class="profile"><select aria-label="ทดลองบทบาท" onchange="role=this.value;branch=role==='พนักงาน'||role==='ผู้จัดการสาขา'?'b1':'all';go('tasks')">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><div class="avatar">${role[0]}</div></div></header><main>${tasks()}</main></div></div>`}
